<?php require __DIR__.'/auth.php'; require_admin(); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Students | StudentHub</title><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="css/style.css"></head><body><main class="max-w-[1200px] mx-auto px-6 py-10"><header class="admin-topbar"><div><p class="eyebrow">ADMIN</p><h1>Manage students</h1></div><a class="admin-logout" href="logout.php">Logout</a></header><section class="admin-panel"><form id="student-form" class="admin-event-form"><label>Name<input name="full_name" required></label><label>Email<input name="email" type="email" required></label><label>Course<input name="department" required></label><button type="submit">Add student</button></form><p id="student-message" role="status" aria-live="polite"></p><label for="student-search">Search name, email or course</label><input id="student-search" type="search"><p id="student-status" role="status" aria-live="polite">Loading...</p><div class="admin-table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Course</th><th>Status</th><th>Actions</th></tr></thead><tbody id="student-rows"></tbody></table></div></section></main><script>const rows=document.getElementById('student-rows'),statusNode=document.getElementById('student-status'),search=document.getElementById('student-search'),form=document.getElementById('student-form'),message=document.getElementById('student-message');let timer;async function load(){statusNode.textContent='Loading...';try{const r=await fetch('api/students.php?q='+encodeURIComponent(search.value));const j=await r.json();rows.replaceChildren();(j.data||[]).forEach(s=>{const tr=document.createElement('tr');tr.innerHTML='<td></td><td></td><td></td><td></td><td><button type="button" data-edit>Edit</button> <button type="button" data-delete>Deactivate</button></td>';[s.full_name,s.email,s.department,s.status].forEach((v,i)=>tr.children[i].textContent=v||'');tr.querySelector('[data-edit]').onclick=async()=>{const name=prompt('Name',s.full_name),email=prompt('Email',s.email),course=prompt('Course',s.department);if(name&&email&&course){const response=await fetch('api/students.php',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({student_id:s.student_id,full_name:name,email,department:course})});const data=await response.json();message.textContent=data.message;load();}};tr.querySelector('[data-delete]').onclick=async()=>{if(confirm('Deactivate this student?')){const response=await fetch('api/students.php',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({student_id:s.student_id})});const data=await response.json();message.textContent=data.message;load();}};rows.append(tr)});statusNode.textContent=(j.data||[]).length+' students found.'}catch(e){statusNode.textContent='Could not load students.'}}form.onsubmit=async event=>{event.preventDefault();const response=await fetch('api/students.php',{method:'POST',body:new FormData(form)});const data=await response.json();message.textContent=data.message;form.reset();load();};search.oninput=()=>{clearTimeout(timer);timer=setTimeout(load,300)};load();</script></body></html>
